import { describe, expect, it } from "vitest";
import { txInputs } from "../src/background/cbor";
import type { KoiosUtxo } from "../src/background/koios";
import { SESSION_MINT } from "../src/background/mint";
import { SESSION_OUT } from "../src/background/sessions";
import { historyTags, madePrivate, merged, receivedIn, type HistoryClass } from "../src/shared/histories";
import type { PendingTx } from "../src/shared/rpc";
import type { Tested } from "./chain-fixtures";
import { loadTestWasm, minswapEstimate, ownedUtxos, testBalances, vectors, withdrawPreprod } from "./fakes";
const PASSWORD = "correct horse battery";
const hash = (h: string) => (h.length === 64 ? h : h.repeat(32));
const inputsOf = (cbor: string) => txInputs(Uint8Array.from(Buffer.from(cbor, "hex")));
const VECTOR = vectors("cardano_account.json").find((v) => v.account === 0 && v.phrase.split(" ").length === 12)!;
const OWN_ADDRESS: string = VECTOR.preprod.receive_0;
async function privateRow(t: Tested, txHash: string, lovelace: string, index = 0): Promise<KoiosUtxo> {
  const wasm = loadTestWasm();
  const bytes = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  return { ...ownedUtxos[0]!, tx_hash: txHash, tx_index: index, value: lovelace, asset_list: [], inline_datum: { bytes, value: null }, block_height: 9_000_001 };
}
async function wallet() {
  const t = testBalances({ owned: false });
  await t.wallet.create(VECTOR.phrase, PASSWORD);
  const evaluation = withdrawPreprod.amount.evaluation as { result: unknown[] };
  t.koios.evaluation = { ...evaluation, result: evaluation.result.slice(0, 1) };
  await t.balances.get("preprod");
  return t;
}
async function spent(t: Tested, kind: PendingTx["kind"], txHash: string, origin: HistoryClass, extra: object = {}) {
  await t.activity.sent("preprod", { kind, network: "preprod", txHash, submittedAt: t.clock.now, confirmations: null }, { lovelace: "20000000", origin, ...extra });
}
async function land(t: Tested, rows: KoiosUtxo[]) { t.koios.added.push(...rows); t.clock.now += 60_000; await t.balances.get("preprod", true); }
async function stealthMint(t: Tested, rows: KoiosUtxo[]) { await land(t, rows); await t.mint.build("preprod", "", "seedelf"); return inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor); }
async function funding(t: Tested, rows: KoiosUtxo[]) { await land(t, rows); await t.sessions.outBuild("preprod", await t.sessions.quote("preprod", minswapEstimate.ask)); return inputsOf((await t.session.get<{ txCbor: string }>(SESSION_OUT))!.txCbor); }
const R0 = hash("c0"), W = hash("57"), A0 = hash("a0");
const as191 = receivedIn(R0);                                   // 1.9.1 withdraw.ts:147
const asHead = merged([receivedIn(R0), madePrivate(0)]);        // this release's tiedBy
async function setUp(makePublic: HistoryClass, own: string, change: string) {
  const t = await wallet();
  await spent(t, "withdraw", W, makePublic, { payments: [{ address: OWN_ADDRESS, lovelace: "20000000", tokens: [], own: true, ownAccount: 0 }] });
  await t.activity.sent("preprod", { kind: "move-in", network: "preprod", txHash: A0, submittedAt: t.clock.now, confirmations: null }, { lovelace: own, origin: madePrivate(0) });
  return { t, own: await privateRow(t, A0, own), change: await privateRow(t, W, change, 1) };
}
describe("l3rank#1: a Make public 1.9.1 sent to the user's own account", () => {
  it("reads as change tied to that account (privacy.md:109, :176)", { timeout: 60_000 }, async () => {
    const { t, change } = await setUp(as191, "10000000", "29800000");
    await land(t, [change]);
    const c = (await t.activity.classes("preprod", [change])).get(`${W}#1`)!;
    expect.soft(["own", "session"]).toContain(c.origin);
    expect(historyTags(c)).toContain("Made private");
  });
  it("a stealth mint takes the 10 ₳ made private, not the old 29.8 ₳ change", { timeout: 60_000 }, async () => {
    const { t, own, change } = await setUp(as191, "10000000", "29800000");
    expect(await stealthMint(t, [own, change])).toEqual([`${A0}#0`]);
  });
  it("control: this release's shape, the mint takes the 10 ₳", { timeout: 60_000 }, async () => {
    const { t, own, change } = await setUp(asHead, "10000000", "29800000");
    expect(await stealthMint(t, [own, change])).toEqual([`${A0}#0`]);
  });
  it("a funding takes the 30 ₳ made private, not the old 49.8 ₳ change", { timeout: 60_000 }, async () => {
    const { t, own, change } = await setUp(as191, "30000000", "49800000");
    expect(await funding(t, [own, change])).toEqual([`${A0}#0`]);
  });
  it("control: this release's shape, the funding takes the 30 ₳", { timeout: 60_000 }, async () => {
    const { t, own, change } = await setUp(asHead, "30000000", "49800000");
    expect(await funding(t, [own, change])).toEqual([`${A0}#0`]);
  });
  it("pin, the finding's numbers (9.8 ₳ change, 50 ₳ made private): both shapes take the change", { timeout: 60_000 }, async () => {
    for (const shape of [as191, asHead]) {
      const { t, own, change } = await setUp(shape, "50000000", "9800000");
      expect(await stealthMint(t, [own, change])).toEqual([`${W}#1`]);
    }
  });
});

