// l3rank#2 (chunk 51, round three's last look, the rank lens). A box's way back the private balance pays (call 36) is
// merged with the paying UTxO's class by REACH (shared/histories.ts merged): a box of unknown making (unplacedBox, rule
// 1 (d)) paid back with a payment received reads origin "received", which core's Purpose::Mint and Fund rank 1, with
// money others paid, at tier 0, no box. And call 36's payer order (lovejoin.ts withdrawOne `fromLovejoin`) takes a box
// of unknown making, origin lovejoin since round three, as a box that ties no account: tied by size with a box the
// wallet knows mixed. Real WebAssembly; the token pool is PR #163's v2 twin, stuck at coins_per_utxo_size 4800 (as
// lovejoin-crediting-review-fixes.test.ts's x-privacy#0 cases).
import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { CONTRACT_V1 } from "../src/background/balances";
import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { LovejoinService, type PoolRef } from "../src/background/lovejoin";
import { SESSION_MINT } from "../src/background/mint";
import type { HistoryClass } from "../src/shared/histories";
import type { PendingTx } from "../src/shared/rpc";
import { CHAINS, POOL, withSession, type Tested } from "./chain-fixtures";
import { bech32, preprodAddress } from "./fixtures/bech32";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, ownedUtxos } from "./fakes";
import { ADA_POOL, adaBox, ownDatum, strangerDatum } from "./v2-pools";

const hash = (h: string) => (h.length === 64 ? h : h.repeat(32));
const inputsOf = (cbor: string) => txInputs(Uint8Array.from(Buffer.from(cbor, "hex")));
const ref = (b: { txHash: string; txIndex: number }) => `${b.txHash}#${b.txIndex}`;
const paidBy = (cred: string) => [{ payment_addr: { bech32: preprodAddress(cred), cred } }];
const unplaced = (w: string): HistoryClass => ({ id: `box:${w}+unknown:${w}`, origin: "lovejoin" });

const FOUND = JSON.parse(readFileSync(new URL("../../wasm/tests/fixtures/lovejoin-v2-token-pool-preprod.json", import.meta.url), "utf8")) as {
  seed: { txHash: string; txIndex: number }; reference: KoiosUtxo; scripts: KoiosUtxo[];
};
const TOKEN_POOL: PoolRef = { reference: FOUND.reference, seed: FOUND.seed, scripts: FOUND.scripts };
const VIEW = JSON.parse(loadTestWasm().lovejoinVerifyPool(JSON.stringify({ network: "preprod", pool: TOKEN_POOL }))) as {
  id: string; mixBoxHash: string; token: { policyId: string; assetName: string; quantity: string };
};
const TOKEN = VIEW.id;
const TOKEN_ADDRESS = bech32("addr_test", Uint8Array.from([0x70, ...Buffer.from(VIEW.mixBoxHash, "hex")]));
const LJTEST = { policy_id: VIEW.token.policyId, asset_name: VIEW.token.assetName, quantity: VIEW.token.quantity, decimals: 0, fingerprint: "asset1ljtest" };
const inToken = (txHash: string) => ({ txHash, txIndex: 0, pool: TOKEN });

type Entry = { txHash: string; kind: string; lovelace: string; origin?: HistoryClass };
const entryOf = async (t: Tested, txHash: string) =>
  (await t.store.get<{ entries: Entry[] }>("history.preprod"))!.entries.find((e) => e.txHash === txHash);

async function privateRow(t: Tested, txHash: string, lovelace: string, tokens: unknown[] = []): Promise<KoiosUtxo> {
  const wasm = loadTestWasm();
  const bytes = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  return { ...ownedUtxos[0]!, tx_hash: txHash, tx_index: 0, value: lovelace, asset_list: tokens, inline_datum: { bytes, value: null }, block_height: 9_000_001 } as KoiosUtxo;
}

async function land(t: Tested, rows: KoiosUtxo[]): Promise<void> {
  t.koios.added.push(...rows);
  t.clock.now += 60_000;
  await t.balances.get("preprod", true);
}

function tokenBox(t: Tested, tx: string, datum: string, mixed: boolean, hours = 5): KoiosUtxo {
  if (mixed) t.koios.txSpends.set(hash(tx), [{ payment_addr: { bech32: TOKEN_ADDRESS, cred: VIEW.mixBoxHash } }]);
  return {
    ...POOL[0]!, tx_hash: hash(tx), tx_index: 0, address: TOKEN_ADDRESS, payment_cred: VIEW.mixBoxHash, value: "2000000",
    block_time: Math.floor(t.clock.now / 1000) - hours * 3600, datum_hash: null, inline_datum: { bytes: datum, value: {} },
    asset_list: [LJTEST as never],
  } as KoiosUtxo;
}

const strangers = (t: Tested) => Array.from({ length: 12 }, (_, i) => tokenBox(t, (0x60 + i).toString(16), strangerDatum(), true));

function witnessed(t: Tested) {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const signed = (request: string) => {
    const { txCbor } = JSON.parse(request) as { txCbor: string };
    return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) });
  };
  return new LovejoinService({
    ...t.deps,
    wasm: { ...wasm, finishLovejoinWithdraw: signed, signScriptSpend: (_key: unknown, request: string) => signed(request) } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store,
    pools: async () => [ADA_POOL, TOKEN_POOL],
    sessionIndices: async () => [0],
    random: () => 0.5,
  });
}

const s1 = () => ownedUtxos.find((u) => (u.asset_list ?? []).some((a) => a.policy_id === CONTRACT_V1.seedelfPolicyId))!;
const spentBy = (t: Tested, pending: PendingTx) => txInputs(t.koios.submitted.find((bytes) => txIdOf(bytes) === pending.txHash)!).sort();

describe("l3rank#2: a box's way back the private balance pays (chunk 51, round three's last look)", CHAINS, () => {
  it("a stranger's box in a stuck token pool, Bring every box back now paying with Bob's 20 ₳: its way back ranks as a payment, and the next stealth mint takes it before Peter's 50 ₳", async () => {
    const { t } = await withSession("40000000");
    await t.balances.get("preprod");
    const bob = await privateRow(t, hash("b0"), "20000000");
    await land(t, [bob]);
    expect((await entryOf(t, bob.tx_hash))?.kind).toBe("received");
    const C = hash("c9");
    t.koios.addedToAccounts.push(tokenBox(t, C, s1().inline_datum!.bytes, false), ...strangers(t));
    t.koios.txSpends.set(C, paidBy("ee".repeat(28)));
    t.koios.params = { coins_per_utxo_size: "4800" };
    const lj = witnessed(t);
    const pool = (await lj.status("preprod")).pools!.find((p) => p.id === TOKEN)!;
    expect((pool.someoneElse ?? []).map(ref)).toEqual([`${C}#0`]);
    await lj.bringAllBack("preprod");
    const sent = await lj.withdrawDue("preprod");
    expect(sent).toHaveLength(1);
    expect(spentBy(t, sent[0]!)).toEqual([`${C}#0`, `${bob.tx_hash}#0`].sort());
    const entry = (await entryOf(t, sent[0]!.txHash))!;
    console.log("way back", sent[0]!.txHash, "origin", JSON.stringify(entry.origin));
    expect.soft(entry.origin?.origin, "the way back of a d = 1 planted box the private balance paid").not.toBe("received");
    t.koios.added = t.koios.added.filter((u) => u.tx_hash !== bob.tx_hash);
    t.koios.addedToAccounts = t.koios.addedToAccounts.filter((u) => u.tx_hash !== C);
    const w = await privateRow(t, sent[0]!.txHash, (BigInt(entry.lovelace) + 20_000_000n).toString(), [LJTEST]);
    const peter = await privateRow(t, hash("b1"), "50000000");
    await land(t, [w, peter]);
    await t.mint.build("preprod", "", "seedelf");
    const minted = inputsOf((await t.session.get<{ txCbor: string }>(SESSION_MINT))!.txCbor);
    console.log("stealth mint spent", JSON.stringify(minted), "W =", `${w.tx_hash}#0`, "Peter =", `${peter.tx_hash}#0`);
    expect(minted, "the stealth mint should take Peter's payment, not the way back tied in the open to S1").toEqual([`${peter.tx_hash}#0`]);
  });

  it("Bring one back paid privately: the payer order takes a box of unknown making as a box, before a larger box the wallet knows mixed", async () => {
    const { t } = await withSession("40000000");
    await t.balances.get("preprod");
    const C = hash("ca");
    t.koios.addedToAccounts.push(adaBox(C, s1().inline_datum!.bytes, t.clock.now));
    t.koios.txSpends.set(C, paidBy("ee".repeat(28)));
    const lj = witnessed(t);
    await lj.status("preprod");
    await lj.bringAllBack("preprod");
    const [planted] = await lj.withdrawDue("preprod");
    expect(planted).toBeDefined();
    const plantedEntry = (await entryOf(t, planted!.txHash))!;
    expect(plantedEntry.origin).toEqual(unplaced(planted!.txHash));
    t.koios.addedToAccounts = t.koios.addedToAccounts.filter((u) => u.tx_hash !== C);
    const w = await privateRow(t, planted!.txHash, plantedEntry.lovelace);
    const M = hash("d7");
    const pending = { kind: "lovejoin-withdraw", network: "preprod", txHash: M, submittedAt: t.clock.now, confirmations: null } as PendingTx;
    await t.activity.sent("preprod", pending, { lovelace: "9700000", fee: "300000", origin: { id: `box:${M}`, origin: "mixed" } });
    const m = await privateRow(t, M, "9700000");
    await land(t, [w, m]);
    const V = hash("d8");
    t.koios.addedToAccounts.push(tokenBox(t, V, await ownDatum(t.wallet), true), ...strangers(t));
    t.koios.params = { coins_per_utxo_size: "4800" };
    const back = await lj.withdrawNow("preprod", inToken(V), false, "private");
    const spent = spentBy(t, back);
    const entry = (await entryOf(t, back.txHash))!;
    console.log("way back of V", JSON.stringify(spent), "W =", `${w.tx_hash}#0`, "M =", `${m.tx_hash}#0`, "origin", JSON.stringify(entry.origin));
    expect(spent, "a box the wallet knows mixed pays before a box of unknown making tied in the open to S1").toEqual([`${V}#0`, `${m.tx_hash}#0`].sort());
  });
});
