    /// The two boxes of l3rank#3: W, the way back of a box whose making the wallet can't place (`box:<w>+unknown:<w>`,
    /// origin lovejoin, what withdrawOne seals for a box Mallory planted under Seedelf S1's register as found, d = 1,
    /// brought back by Bring every box back now), and X, the way back of a box the wallet recorded a mix moving
    /// (`box:<x>`, origin mixed). One of them `less` lovelace smaller: the withdraw fees' difference.
    fn w_and_x(w: &World, w_less: bool, less: u64) -> [(UtxoResponse, Class); 2] {
        let (w_lovelace, x_lovelace) = if w_less { (BOX - less, BOX) } else { (BOX, BOX - less) };
        let unplaced = owned(w, 0x30, 0, w_lovelace, &[]);
        let mixed = owned(w, 0x40, 0, x_lovelace, &[]);
        let unplaced_class = class(&format!("box:{0}+unknown:{0}", unplaced.tx_hash), Origin::Lovejoin);
        let mixed_class = class(&format!("box:{}", mixed.tx_hash), Origin::Mixed);
        [(unplaced, unplaced_class), (mixed, mixed_class)]
    }

