                table.push(format!("{name}, {}: spent {which}, ranks W {} X {}",
                    if w_less { "W 300 lovelace smaller" } else { "X 300 lovelace smaller" }, h.rank_of(&unplaced), h.rank_of(&mixed)));
                picked.push(which);
            }
            if picked[0] != picked[1] { flipped.push(format!("{name}: {picked:?}")); }
        }
        eprintln!("{}", table.join("\n"));
        assert!(flipped.is_empty(), "a few hundred lovelace decide which box these spend:\n{}", flipped.join("\n"));
    }

    /// A pin for l3rank#3's fix, either way: a stealth mint takes the box a mix moved whatever their sizes.
    #[test]
    fn l3rank_3_a_stealth_mint_takes_the_mixed_box_whatever_the_sizes() {
        let w = world();
        for w_less in [true, false] {
            let [(unplaced, unplaced_class), (mixed, mixed_class)] = w_and_x(&w, w_less, 300);
            let known = [(&unplaced, unplaced_class), (&mixed, mixed_class)];
            assert_eq!(minted(&w, &known), one(&mixed), "W smaller: {w_less}");
        }
    }
