```ts
// Chunk 51, l3misc#1. Round three covered every .rs file under seedelf-data/ (l2docs#1) for one check that reads them,
// docs#11's: nothing there includes a Markdown file. So a pull request that changes only the data layer's Rust, an API
// fix, ran the wallet's whole check (rust, wasm, unit, e2e and store, about 13 minutes) and couldn't merge before it
// passed, though nothing else in that check reads the data layer. data-layer.yml starts on that pull request anyway, so
// the check runs there, in seconds, and the wallet's check stays out of it.
describe("a pull request that changes only the data layer's Rust", () => {
  const ROOT = fileURLToPath(new URL("../../../../", import.meta.url));
  const RS = ["seedelf-data/api/src/public/utxos.rs", "seedelf-data/api/src/main.rs", "seedelf-data/api/tests/common/mod.rs"];

  /** Whether web-wallet.yml's check runs for a pull request into main changing only `path`: awk alone decides. */
  function walletRuns(path: string): boolean {
    const text = readFileSync(new URL("web-wallet.yml", WORKFLOWS), "utf8");
    const from = text.indexOf("covered='") + "covered='".length;
    const awk = spawnSync("awk", [text.slice(from, text.indexOf("'", from))], { input: `${path}\n`, encoding: "utf8" });
    expect(awk.stderr).toBe("");
    return awk.status === 0;
  }

  it("starts the data layer's check, not the wallet's", () => {
    for (const path of RS) expect(startsOn("data-layer.yml", path), path).toBe(true);
    expect(RS.filter((path) => walletRuns(path))).toEqual([]);
  });

  it("runs, in a workflow it starts, a step that fails on a crate including its README and passes on the tree", () => {
    const starting = workflows()
      .map(({ file }) => file)
      .filter((file) => startsOn(file, RS[0]!));
    const steps = scripts().filter(
      ({ where, lines }) =>
        starting.includes(where.split(":")[0]!) && lines.some((line) => !comment(line) && /include_/.test(line)),
    );
    expect(steps.map((s) => s.where)).toEqual([expect.stringMatching(/^data-layer\.yml:/)]);
    const tmp = mkdtempSync(join(tmpdir(), "l3misc-"));
    try {
      mkdirSync(join(tmp, "seedelf-data/api/src"), { recursive: true });
      writeFileSync(join(tmp, "seedelf-data/api/src/lib.rs"), '#![doc = include_str!(\n    "../../README.md"\n)]\n');
      for (const step of steps) {
        // A run: step with no shell: key runs on ubuntu as `bash -e {0}`, in the job's working-directory, seedelf-data/.
        const run = (cwd: string) => spawnSync("bash", ["-ec", step.lines.join("\n")], { cwd, encoding: "utf8" }).status;
        expect(run(join(tmp, "seedelf-data")), `${step.where} on a crate that includes its README`).not.toBe(0);
        expect(run(join(ROOT, "seedelf-data")), `${step.where} on the tree as it is`).toBe(0);
      }
    } finally {
      rmSync(tmp, { recursive: true, force: true });
    }
  });
});
