import { describe, expect, it } from "vitest";
import { CONTRACT_V1 } from "../src/background/balances";
import { txInputs } from "../src/background/cbor";
import { Collateral } from "../src/background/collateral";
import type { KoiosUtxo } from "../src/background/koios";
import { LovejoinService, type PoolRef } from "../src/background/lovejoin";
import type { HistoryClass } from "../src/shared/histories";
import { CHAINS, POOL, withSession, type Tested } from "./chain-fixtures";
import { bech32, preprodAddress } from "./fixtures/bech32";
import { txIdOf } from "./fixtures/cbor";
import { loadTestWasm, madeByMix, ownedUtxos } from "./fakes";
import { ADA, ADA_POOL, adaBox, ownDatum, strangerDatum } from "./v2-pools";

const FOUND_V2 = JSON.parse(readFileSync(new URL("../../wasm/tests/fixtures/lovejoin-v2-token-pool-preprod.json", import.meta.url), "utf8")) as { seed: { txHash: string; txIndex: number }; reference: KoiosUtxo; scripts: KoiosUtxo[] };
const TOKEN_POOL: PoolRef = { reference: FOUND_V2.reference, seed: FOUND_V2.seed, scripts: FOUND_V2.scripts };
const VIEW = JSON.parse(loadTestWasm().lovejoinVerifyPool(JSON.stringify({ network: "preprod", pool: TOKEN_POOL }))) as { id: string; mixBoxHash: string; token: { policyId: string; assetName: string; quantity: string } };
const TOKEN = VIEW.id;
const LJTEST = VIEW.token.policyId + VIEW.token.assetName;
const TOKEN_ADDRESS = bech32("addr_test", Uint8Array.from([0x70, ...Buffer.from(VIEW.mixBoxHash, "hex")]));
const hash = (h: string) => (h.length === 64 ? h : h.repeat(32));
const ref = (b: { txHash: string; txIndex: number }) => `${b.txHash}#${b.txIndex}`;
const inAda = (txHash: string) => ({ txHash, txIndex: 0, pool: ADA });
const paidBy = (cred: string) => [{ payment_addr: { bech32: preprodAddress(cred), cred } }];
type Entry = { txHash: string; kind: string; lovelace: string; origin?: HistoryClass };
const entryOf = async (t: Tested, txHash: string) => (await t.store.get<{ entries: Entry[] }>("history.preprod"))!.entries.find((e) => e.txHash === txHash);

async function privateRow(t: Tested, txHash: string, lovelace: string): Promise<KoiosUtxo> {
  const wasm = loadTestWasm();
  const bytes = await t.wallet.withKeys((keys) => Buffer.from(wasm.registerToDatum(wasm.rerandomize(keys.seedelf.baseRegister()))).toString("hex"));
  return { ...ownedUtxos[0]!, tx_hash: txHash, tx_index: 0, value: lovelace, asset_list: [], inline_datum: { bytes, value: null }, block_height: 9_000_001 };
}
async function tokenBox(t: Tested, tx: string, ours: boolean, hours = 5): Promise<KoiosUtxo> {
  t.koios.txSpends.set(tx.repeat(32), [{ payment_addr: { bech32: TOKEN_ADDRESS, cred: VIEW.mixBoxHash } }]);
  return { ...POOL[0]!, tx_hash: tx.repeat(32), tx_index: 0, address: TOKEN_ADDRESS, payment_cred: VIEW.mixBoxHash, value: "2000000",
    block_time: Math.floor(t.clock.now / 1000) - hours * 3600, datum_hash: null,
    inline_datum: { bytes: ours ? await ownDatum(t.wallet) : strangerDatum(), value: {} },
    asset_list: [{ policy_id: VIEW.token.policyId, asset_name: VIEW.token.assetName, quantity: VIEW.token.quantity, decimals: 0, fingerprint: "asset1ljtest" } as never] } as KoiosUtxo;
}
function witnessed(t: Tested) {
  const wasm = loadTestWasm();
  t.collateral.answer = { status: 200, body: { witness: "a1008182" } };
  const self = (request: string) => { const { txCbor } = JSON.parse(request) as { txCbor: string }; return JSON.stringify({ txCbor, txHash: txIdOf(Uint8Array.from(Buffer.from(txCbor, "hex"))) }); };
  return new LovejoinService({ ...t.deps,
    wasm: { ...wasm, finishLovejoinWithdraw: self, signScriptSpend: (_key: unknown, request: string) => self(request) } as typeof wasm,
    collateral: () => new Collateral("https://www.giveme.my/preprod/collateral/", t.collateral.fetch),
    store: t.store, pools: async () => [ADA_POOL, TOKEN_POOL], sessionIndices: async () => [0] });
}

describe("a stuck box's way back paid from the private balance (chunk 51, l3still#2)", CHAINS, () => {
  it("never spends a planted box's way back before a box a mix moved", async () => {
    const { t } = await withSession("40000000");
    await t.balances.get("preprod");
    const s1 = ownedUtxos.find((u) => (u.asset_list ?? []).some((a) => a.policy_id === CONTRACT_V1.seedelfPolicyId))!;
    const C = hash("c9");
    t.koios.addedToAccounts.push(adaBox(C, s1.inline_datum!.bytes, t.clock.now)); // Mallory's 5 ₳ box, S1's register as found
    t.koios.txSpends.set(C, paidBy("ee".repeat(28)));
    const X = hash("a7");
    madeByMix(t.koios, X); // a 10 ₳ classic box of the wallet's that someone else's mix made
    const classic = { ...POOL[0]!, tx_hash: X, tx_index: 0, block_time: Math.floor(t.clock.now / 1000) - 7 * 3600, inline_datum: { bytes: await ownDatum(t.wallet), value: {} } } as KoiosUtxo;
    const B = await tokenBox(t, "f1", true, 7);
    const strangers = await Promise.all(Array.from({ length: 12 }, (_, i) => tokenBox(t, (0x60 + i).toString(16), false)));
    t.koios.addedToAccounts.push(...POOL, classic, B, ...strangers);
    const lj = witnessed(t);
    const ada = (await lj.status("preprod")).pools!.find((p) => p.id === ADA)!;
    expect((ada.someoneElse ?? []).map(ref)).toEqual([ref(inAda(C))]);
    const w = await lj.withdrawNow("preprod", inAda(C), true);
    const wEntry = (await entryOf(t, w.txHash))!;
    expect(wEntry.origin).toEqual({ id: `box:${w.txHash}+unknown:${w.txHash}`, origin: "lovejoin" });
    await lj.status("preprod");
    const m = await lj.withdrawNow("preprod", { txHash: X, txIndex: 0 });
    const mEntry = (await entryOf(t, m.txHash))!;
    expect(mEntry.origin).toEqual({ id: `box:${m.txHash}`, origin: "mixed" });
    t.koios.added.push(await privateRow(t, w.txHash, wEntry.lovelace), await privateRow(t, m.txHash, mEntry.lovelace));
    t.clock.now += 60_000;
    await t.balances.get("preprod", true);
    const classes = await t.activity.classes("preprod", [await privateRow(t, w.txHash, wEntry.lovelace)]);
    expect(classes.get(`${w.txHash}#0`)?.origin).toBe("lovejoin");
    expect(BigInt(wEntry.lovelace) < BigInt(mEntry.lovelace)).toBe(true);
    t.koios.params = { coins_per_utxo_size: "4800", epoch_no: 291 }; // next epoch: the token pool is stuck
    await lj.status("preprod");
    expect(await lj.stuck("preprod", (await lj.poolsOf("preprod", LJTEST))[0]!)).toBe(true);
    const back = await lj.withdrawNow("preprod", { txHash: B.tx_hash, txIndex: 0, pool: TOKEN }, false, "private");
    const inputs = txInputs(t.koios.submitted.find((bytes) => txIdOf(bytes) === back.txHash)!);
    expect(inputs).toContain(`${B.tx_hash}#0`);
    expect(inputs, "the planted box's way back, which anyone reading S1's name can follow").not.toContain(`${w.txHash}#0`);
    expect(inputs, "the way back of a box a mix moved, which ties nothing").toContain(`${m.txHash}#0`);
  });
});
