// The last look at round three, l3still#3. l2docs#1 put every .rs file under seedelf-data/ in covered, so a pull
// request that changes only the data layer's Rust runs the web wallet's five jobs, about 13 minutes on the check main's
// ruleset requires, where before it skipped them and Web Wallet required went green at once. All that run checks for
// it is docs#11's rule: none of that Rust includes a .md file. data-layer.yml starts on every such pull request, so it
// makes that check itself, and the data layer's pull requests stay out of the wallet's check, as the CI-speed rule asks.
describe("a pull request that changes only the data layer's Rust", () => {
  const ROOT = fileURLToPath(new URL("../../../../", import.meta.url));

  /** Whether web-wallet.yml's check runs for a pull request into main that changes only `path`. */
  function walletRuns(path: string): boolean {
    const text = readFileSync(new URL("web-wallet.yml", WORKFLOWS), "utf8");
    const from = text.indexOf("covered='") + "covered='".length;
    const awk = spawnSync("awk", [text.slice(from, text.indexOf("'", from))], { input: `${path}\n`, encoding: "utf8" });
    expect(awk.stderr).toBe("");
    return awk.status === 0;
  }

  it("skips the web wallet's check, and data-layer.yml holds that Rust to docs#11's rule itself", () => {
    const rs = "seedelf-data/api/src/lovejoin/standard.rs";
    // Not vacuous: the data layer's own check starts on it.
    expect(startsOn("data-layer.yml", rs)).toBe(true);
    expect.soft(walletRuns(rs), "web-wallet.yml's check runs on it").toBe(false);

    // data-layer.yml's step that reads the includes, written as a block: YAML reads a plain `run: ! grep …` as a tag
    // on the string `grep …`, and drops the `!`.
    const steps = scripts().filter(
      ({ where, lines }) => where.startsWith("data-layer.yml:") && lines.some((line) => !comment(line) && /include_/.test(line)),
    );
    expect(steps.map(({ where }) => where), "data-layer.yml's steps that read the includes").toEqual([expect.any(String)]);
    const step = steps[0]!;
    expect(step.lines.length > 1 || !/^!/.test(step.lines[0]!.trim()), `${step.where} is a plain scalar starting with !`).toBe(true);

    // Run as a step with no shell: key runs on ubuntu (`bash -e {0}`), where the check job runs its steps: seedelf-data/,
    // its defaults' working-directory.
    const run = (cwd: string) => spawnSync("bash", ["-e", "-c", step.lines.join("\n")], { cwd, encoding: "utf8" }).status;
    const tmp = mkdtempSync(join(tmpdir(), "l3still-"));
    try {
      for (const [name, source] of [
        ["on one line", '#![doc = include_str!("../../README.md")]\n'],
        // As rustfmt wraps a long include here (datum.rs, standard.rs, templates.rs, live_public.rs).
        ["wrapped", 'const DOC: &str = include_str!(\n    "../../README.md"\n);\n'],
        ["as bytes", 'const DOC: &[u8] = include_bytes!("../NOTES.md");\n'],
      ] as const) {
        const crate = join(tmp, name.replaceAll(" ", "-"), "seedelf-data");
        mkdirSync(join(crate, "api/src"), { recursive: true });
        writeFileSync(join(crate, "api/src/lib.rs"), source);
        expect.soft(run(crate), `${step.where} on a crate that includes Markdown ${name}`).not.toBe(0);
      }
      expect(run(join(ROOT, "seedelf-data")), `${step.where} on the tree as it is`).toBe(0);
    } finally {
      rmSync(tmp, { recursive: true, force: true });
    }
  });
});
