  const t = testBalances();
  await t.wallet.create(account.phrase, PASSWORD);
  await t.preferences.set({ dappConnector: true, spendRewards: false });
  return t;
}
type T = Awaited<ReturnType<typeof on>>;
const inside = (t: T) => t.dapp as unknown as { spared: Map<string, unknown>; unlocking: unknown[]; refusedUntil: Map<string, unknown> };
function holdSites(t: T) {
  const realGet = t.store.get.bind(t.store) as (name: string) => Promise<unknown>;
  let release!: () => void;
  const gate = new Promise<void>((r) => (release = r));
  const state = { reads: 0 };
  t.store.get = (async (name: string) => { if (name === "dapps") { state.reads++; await gate; } return realGet(name); }) as typeof t.store.get;
  return { state, done: () => { release(); t.store.get = realGet as typeof t.store.get; } };
}
